# -*- coding: utf-8 -*-
# Ampliación del pack AP (AP24–AP47): textos que leí yo mismo en la página original (ʿAbd al-Razzaq, Saʿid ibn Mansur,
# Muwatta', Mudawwana, Ibn al-Mundhir, Ibn Qudama, Ibn Rushd).
HU = "hadithunlocked.com (texto árabe y cadena; página web, no edición impresa)"
USO = "Pack «Apostasía en las fuentes islámicas tempranas»"
SH = "shamela.ws (texto de la Biblioteca Shamela; la página impresa va en el título de cada página)"
ARZ = "ʿAbd al-Razzaq al-Sanʿani (m. 211 H), al-Musannaf, n.º {n}, capítulo «Bab fi l-kufr baʿd al-iman» (numeración y capítulo según hadithunlocked; no he comprobado volumen y página de la edición impresa)"
NOGRADO = "La página no da calificación de la cadena («no se conoce dictamen»); no la evalúo."
APX = [
 dict(id="AP24", key="ARZ1", tag="Compañeros · ʿAbd al-Razzaq 18773 · ʿUmar y Tustar", specs=["AP-ar18773"],
  title="ʿAbd al-Razzaq 18773: ʿUmar, al saber que en Tustar mataron a un apóstata: «¿por qué no le cerrasteis una puerta, le dejasteis un ventanuco, un pan al día y un jarro de agua tres días, y al tercero le ofrecisteis el islam?»",
  ref=ARZ.format(n="18773"), ar_ref="مصنف عبد الرزاق ١٨٧٧٣", site=HU, url="https://hadithunlocked.com/abdalrazzaq:18773",
  es=["Nos informó ʿAbd al-Razzaq, de Maʿmar, dijo: me informó Muhammad ibn ʿAbd al-Rahman ibn ʿAbd al-Qari, de su padre, que dijo: Vino Mujzaʾa ibn Thawr —o Shaqiq ibn Thawr— a ʿUmar para darle la buena noticia de la conquista de Tustar; no lo halló en Medina, pues estaba ausente, en una tierra suya; fue a verlo y, al acercarse al huerto en que estaba, gritó «¡Dios es más grande!»; ʿUmar oyó su grito y respondió «¡Dios es más grande!»; y así siguieron, uno y otro, hasta encontrarse. Dijo ʿUmar: «¿Qué traes?» Dijo: «Te lo ruego por Dios, Príncipe de los Creyentes: Dios nos ha abierto Tustar, que es así y así, y es de tierra de Basora» —y temía que [ʿUmar] la pasara a Kufa—. Dijo: «Sí, es de tierra de Basora. Y bien: ¿hubo alguna noticia de lejos que nos cuentes?» Dijo: «No, [[k:salvo que un hombre de los árabes apostató y le cortamos el cuello.]]» Dijo ʿUmar: [[k:«¡Ay de vosotros! ¿Por qué no le cerrasteis una puerta con barro y le abristeis un ventanuco,]] [[a:le dabais por él cada día un pan y le dabais de beber un jarro de agua durante tres días,]] [[k:y luego le ofrecisteis el islam el tercer día,]] [[a:por si volvía?»]] Luego dijo: [[a:«¡Oh Dios! No estuve presente, no [lo] ordené y no [lo] supe…»]]"],
  prueba="ʿUmar, al enterarse de que sus gobernadores habían ejecutado a un apóstata, no aprueba cómo se hizo: dice lo que debía haberse hecho (encerrarlo tres días con pan y agua y ofrecerle el islam el tercer día, «por si volvía») y se desvincula de la ejecución. Es una de las bases del plazo de tres días y de la petición de arrepentimiento.",
  ojo="Es el mismo episodio que AP09 (Ibn Abi Shayba 30925), AP31 (Saʿid ibn Mansur 2586) y AP34 (Muwatta' 36-26), con detalles distintos (aquí: puerta cerrada con barro y ventanuco, tres días, jarro de agua, oferta el tercer día). Esta versión no dice que se deba matar si el hombre rechaza: solo «por si volvía»; otras versiones sí lo añaden (AP09: «y si no, lo matabais»; el editor la califica de débil). " + NOGRADO + " Y lo que reprocha ʿUmar es el procedimiento, no que se mate al apóstata.", uso=USO),

 dict(id="AP25", key="ARZ2", tag="Compañeros · ʿAbd al-Razzaq 18787 · ʿAli y un anciano cristiano converso", specs=["AP-ar18787"],
  title="ʿAbd al-Razzaq 18787: ʿAli indaga si el converso apostató por una herencia o un matrimonio; al negarse a volver («hasta que me encuentre con el Mesías, no») lo ejecuta",
  ref=ARZ.format(n="18787"), ar_ref="مصنف عبد الرزاق ١٨٧٨٧", site=HU, url="https://hadithunlocked.com/abdalrazzaq:18787",
  es=["Nos informó ʿAbd al-Razzaq, de Maʿmar, de al-Aʿmash, de Abu ʿAmr al-Shaybani, que dijo: Trajeron a ʿAli un anciano que había sido cristiano, se había hecho musulmán y luego había apostatado del islam. Le dijo ʿAli: [[a:«¿Quizá apostataste para conseguir una herencia y luego volver al islam?»]] Dijo: «No». Dijo: [[a:«¿O quizá pediste a una mujer en matrimonio, no te la quisieron dar, y quisiste casarte con ella y luego volver al islam?»]] Dijo: «No». Dijo: [[k:«Pues vuelve al islam.»]] Dijo: [[a:«No: ¡hasta que me encuentre con el Mesías, no!»]] Dijo: Entonces [ʿAli] [[k:ordenó que lo mataran a cuello cortado,]] y su herencia fue entregada a sus hijos musulmanes."],
  prueba="Un caso de apostasía abierta y deliberada atribuido a ʿAli: primero descarta motivos oportunistas (herencia, boda); luego le ofrece volver; ante la negativa expresa del hombre, lo ejecuta y deja la herencia a sus hijos musulmanes.",
  ojo="No es una ejecución sumaria: ʿAli pregunta antes por los motivos y ofrece volver, pero no se menciona un plazo de tres días ni cárcel. La herencia va a los hijos musulmanes, no a la comunidad de los musulmanes como en la Mudawwana (AP36). " + NOGRADO + " Es una colección del siglo III H y el relato es de un transmisor (Abu ʿAmr al-Shaybani) que cuenta lo que se decía de ʿAli.", uso=USO),

 dict(id="AP26", key="ARZ3", tag="Compañeros · ʿAbd al-Razzaq 18788 · ʿAli y Mustawrid al-ʿIjli", specs=["AP-ar18788"],
  title="ʿAbd al-Razzaq 18788: Mustawrid al-ʿIjli se hizo cristiano; ʿAli le pidió que se arrepintiera, no lo hizo, lo mató; los cristianos ofrecieron treinta mil por el cadáver y ʿAli lo quemó",
  ref=ARZ.format(n="18788") + "; la misma historia, con otra cadena, en n.º 18789 (no capturada)", ar_ref="مصنف عبد الرزاق ١٨٧٨٨", site=HU, url="https://hadithunlocked.com/abdalrazzaq:18788",
  es=["Nos informó ʿAbd al-Razzaq, de Ibn ʿUyayna, de Sulayman al-Shami, de Abu ʿAmr al-Shaybani, que [[k:Mustawrid al-ʿIjli se hizo cristiano después de haber sido musulmán,]] y ʿUtba ibn Farqad lo envió a ʿAli, [[k:y [ʿAli] le pidió que se arrepintiera; no se arrepintió; y lo mató.]] [[a:Los cristianos pidieron su cadáver por treinta mil, pero ʿAli se negó y lo quemó.]] Dijo Ibn ʿUyayna: y me informó ʿAmmar al-Duhni que ʿAli le pidió que se arrepintiera cuando [ʿAli] quería hacer la oración, y le dijo: «Pido ayuda a Dios contra ti». Dijo: «Y yo pido ayuda al Mesías contra ti». Dijo: Entonces [[a:ʿAli llevó la mano a su cuello y se encontró con una cruz, y la cortó,]] y dijo: [[k:«¡Matadlo, siervos de Dios!»]] Dijo: Luego, cuando ʿAli entró en la oración, puso a un hombre delante [como imán] y se fue; después informó a la gente de que no lo había hecho por una falta de pureza, sino que había tocado estas impurezas y quiso renovar la ablución."],
  prueba="Segundo testimonio de ʿAli con un caso concreto (Mustawrid al-ʿIjli, que se hizo cristiano tras ser musulmán): pide el arrepentimiento, el hombre se niega y lo mata. Confirma, por otra colección y otra cadena, lo que ya contaba Ibn Abi Shayba 34960 (AP10).",
  ojo="Lo mató y luego quemó el cadáver: en AP02 (Bujari 3017) es el mismo ʿAli quien quema a unos hombres vivos y Ibn Abbas le reprocha el fuego; aquí la versión dice que mató primero y quemó el cuerpo después, y Ibn Qudama (AP41) sostiene que no se debe quemar. La segunda parte (ʿAmmar al-Duhni) es una versión añadida por Ibn ʿUyayna con otro transmisor, con otros detalles. " + NOGRADO, uso=USO),

 dict(id="AP27", key="ARZ4", tag="Compañeros · ʿAbd al-Razzaq 18786 · Ibn Masʿud, Ibn al-Nawwaha y el destierro", specs=["AP-ar18786"],
  title="ʿAbd al-Razzaq 18786: Ibn Masʿud mata a Ibn al-Nawwaha, seguidor de Musaylima, y a los demás los destierra a Siria «hasta que Dios les dé el arrepentimiento o la peste los extermine»",
  ref=ARZ.format(n="18786"), ar_ref="مصنف عبد الرزاق ١٨٧٨٦", site=HU, url="https://hadithunlocked.com/abdalrazzaq:18786",
  trnote="Traducción literal propia; entre corchetes, aclaraciones. La frase «لا أجزرهم اليوم الشيطان» es poco clara; la traduzco de forma aproximada. ",
  es=["Nos informó ʿAbd al-Razzaq, de Ibn ʿUyayna, de Ismaʿil ibn Abi Jalid, de Qays ibn Abi Hazim, que dijo: Vino un hombre a Ibn Masʿud y le dijo: «He pasado junto a una mezquita de los Banu Hanifa y les oí recitar algo que Dios no ha hecho descender: ‹Las que muelen molienda, las que amasan amasijo, las que hornean pan, las que engullen bocado›.» Dijo: [[k:Ibn Masʿud hizo adelantar a Ibn al-Nawwaha ante ellos y lo mató;]] y le pareció demasiado [matar] al resto, y dijo: [[a:«No se los voy a dar hoy al Demonio [como carne de degüello]; desterradlos a Siria, hasta que Dios les conceda el arrepentimiento o la peste los extermine.»]]"],
  prueba="Otra versión del caso de Ibn al-Nawwaha: Ibn Masʿud ejecuta a Ibn al-Nawwaha, el seguidor de Musaylima, y a los demás que recitaban lo de Musaylima los destierra a Siria «hasta que Dios les conceda el arrepentimiento o la peste los extermine».",
  ojo="Aquí no hay pedido de arrepentimiento ni ejecución general: la medida con el resto es el destierro. Otras versiones (Abu Dawud 2762, Ibn Qudama 9/7) dicen que se arrepintieron y los dejó libres, salvo Ibn al-Nawwaha. La ejecución de Ibn al-Nawwaha se liga a su papel de enviado de Musaylima (AP11): no es solo apostasía. " + NOGRADO, uso=USO),

 dict(id="AP28", key="ARZ5", tag="Disidencia · ʿAbd al-Razzaq 18775 · Ibrahim al-Nakhaʿi y al-Thawri", specs=["AP-ar18775"],
  title="ʿAbd al-Razzaq 18775: Ibrahim [al-Nakhaʿi] sobre el apóstata: «se le pide el arrepentimiento siempre [abadan]»; al-Thawri: «esto es lo que nosotros adoptamos»",
  ref=ARZ.format(n="18775"), ar_ref="مصنف عبد الرزاق ١٨٧٧٥", site=HU, url="https://hadithunlocked.com/abdalrazzaq:18775",
  es=["Nos informó ʿAbd al-Razzaq, de al-Thawri, de ʿAmr ibn Qays, de Ibrahim [al-Nakhaʿi], que dijo sobre el apóstata: [[k:«Se le pide el arrepentimiento siempre [abadan].»]] [[a:Dijo Sufyan [al-Thawri]: «Esto es lo que nosotros adoptamos.»]]"],
  prueba="Confirma la frase «yustatab abadan» («se le pide arrepentimiento siempre») atribuida a Ibrahim al-Nakhaʿi, y añade que al-Thawri (m. 161 H), que la transmite, declara adoptarla. Es la disidencia clásica más clara respecto a la ejecución, si se entiende que nunca llega el momento de matar.",
  ojo="Corrige lo que yo había dicho antes (AP21, AP22): la formulación «abadan» sí existe; la leí en ʿAbd al-Razzaq y Ibn Qudama (AP41) la cita igual. Ibn Qudama la entiende como que «nunca se le mataría» y la rechaza por contraria a la sunna y al consenso; pero el texto de ʿAbd al-Razzaq no dice «nunca se mata». Ibn Qudama también cuenta a al-Nakhaʿi entre quienes piden arrepentimiento tres días (AP40), de modo que su postura exacta no está clara. El mismo capítulo trae a continuación (18776, no capturado) un dicho de Ibrahim: «se decía: evitad los castigos [hudud] a los musulmanes cuanto podáis… que el gobernante se equivoque perdonando es mejor que equivocarse castigando». " + NOGRADO, uso=USO),

 dict(id="AP29", key="ARZ6", tag="Contrario · ʿAbd al-Razzaq 18791 · ʿUmar ibn ʿAbd al-ʿAziz", specs=["AP-ar18791"],
  title="ʿAbd al-Razzaq 18791: ʿUmar ibn ʿAbd al-ʿAziz: «pregúntale por las normas del islam; si las conocía, ofrécele el islam y, si se niega, córtale el cuello; si no las conocía, agrava la yizya y déjalo»",
  ref=ARZ.format(n="18791"), ar_ref="مصنف عبد الرزاق ١٨٧٩١", site=HU, url="https://hadithunlocked.com/abdalrazzaq:18791",
  es=["Nos informó ʿAbd al-Razzaq, de Maʿmar, de Simak ibn al-Fadl, que ʿUrwa escribió a ʿUmar ibn ʿAbd al-ʿAziz sobre un hombre que se había hecho musulmán y luego apostató, y ʿUmar le escribió: [[a:«Pregúntale por las normas del islam;]] si ya las conocía, [[k:ofrécele el islam y, si se niega, córtale el cuello;]] [[a:y si no las conocía, agrava la yizya y déjalo.»]]"],
  prueba="El califa ʿUmar ibn ʿAbd al-ʿAziz (m. 101 H) ordena ejecutar al apóstata que conocía el islam y se niega a volver, pero no al que no conocía sus normas: a ése se le agrava la yizya y se le deja. La ejecución se condiciona al conocimiento y a la negativa.",
  ojo="Es una práctica de un califa y su gobernador, no un texto del Profeta; sirve de matiz, no de prueba general. El texto solo dice «ʿUrwa»: no sé de qué ʿUrwa se trata. Se corresponde con la lectura de que la pena exige que el apóstata sepa lo que abandona. " + NOGRADO, uso=USO),

 dict(id="AP30", key="ARZ7", tag="Contrario · ʿAbd al-Razzaq 18792 · ʿUmar ibn ʿAbd al-ʿAziz y la Yazira", specs=["AP-ar18792"],
  title="ʿAbd al-Razzaq 18792: unos conversos de la Yazira apostatan al poco tiempo; ʿUmar ibn ʿAbd al-ʿAziz: «vuelve a imponerles la yizya y déjalos»",
  ref=ARZ.format(n="18792"), ar_ref="مصنف عبد الرزاق ١٨٧٩٢", site=HU, url="https://hadithunlocked.com/abdalrazzaq:18792",
  trnote="Traducción literal propia; entre corchetes, aclaraciones. «رُدَّ عَلَيْهِمُ الْجِزْيَةَ» admite «devuélveles la yizya» o «restablece sobre ellos la yizya»; traduzco lo segundo por el contexto de 18791. ",
  es=["Nos informó ʿAbd al-Razzaq, de Maʿmar, dijo: me informó gente de la Yazira [[k:que unos [hombres] se hicieron musulmanes y no pasó mucho tiempo antes de que apostataran;]] y Maymun ibn Mihran escribió sobre ellos a ʿUmar ibn ʿAbd al-ʿAziz, [[a:y ʿUmar le escribió: «Vuelve a imponerles la yizya y déjalos.»]]"],
  prueba="Un caso del mismo califa que en 18791 ordena ejecutar al apóstata informado: unos conversos recientes que vuelven a su religión no son ejecutados; se les restablece la yizya y se les deja.",
  ojo="El verbo «radda ʿalayhim al-yizya» es ambiguo (devolverles el dinero de la yizya vs. volver a imponérsela); traduzco lo segundo por el contexto de 18791 (agravar la yizya y dejarlo), pero no es seguro. El relato lo da «gente de la Yazira» sin nombre: es testimonio muy indirecto. " + NOGRADO + " Muestra que, en la práctica de ese califa, la pena no se aplicaba a todo el que volvía a su religión.", uso=USO),

 dict(id="AP31", key="SM1", tag="Compañeros · Saʿid ibn Mansur 2586 · ʿUmar y Tustar", specs=["AP-sm2586"],
  title="Saʿid ibn Mansur 2586: ʿUmar: «¿no lo metisteis en una casa y le cerrasteis con barro [la puerta] tres [días] y le arrojasteis cada día un pan, por si volvía?»",
  ref="Saʿid ibn Mansur (m. 227 H), Sunan (ed. al-Aʿzami), «Kitab al-yihad», «Bab ma yaʾ fi l-futuh», n.º 2586, vol. 2 pp. 266-267", ar_ref="سنن سعيد بن منصور ٢٥٨٦", site=SH, url="https://shamela.ws/book/13122/2639",
  es=["[…] [El enviado preguntó:] «¿Tustar es de la jurisdicción de Basora?» Dijo [ʿUmar]: «Sí, es de la jurisdicción de Basora.» Y le entregó la carta. Le dijo ʿUmar: «Infórmame del estado de la gente.» Dijo: [[k:«Un hombre de los árabes apostató del islam; lo acercamos y le cortamos el cuello.»]] Dijo: [[k:«¿No lo metisteis en una casa y le cerrasteis con barro [la puerta] tres [días],]] [[a:y le arrojasteis cada día un pan, por si volvía? ¡Oh Dios! No estuve presente, no [lo] ordené y no [lo] aprobé cuando me llegó.»]]"],
  prueba="Tercera colección independiente (Saʿid ibn Mansur, m. 227 H) que recoge el episodio de ʿUmar y el apóstata de Tustar: ʿUmar reprocha que lo mataran sin darle plazo, y se desvincula de la ejecución.",
  ojo="Coincide en lo esencial con Muwatta' 36-26, ʿAbd al-Razzaq 18773 e Ibn Abi Shayba 30925 (AP34, AP24, AP09); varía el detalle: aquí no dice que haya que matar si no vuelve. La cadena empieza «Yaʿqub ← su padre ← su abuelo» y la página no da calificación (el editor no figura en la captura); no la evalúo. El pasaje que no capturé (antes de la nota ⦗267⦘) es la discusión sobre si Tustar es de Basora o de Kufa. Texto de Shamela.", uso=USO),

 dict(id="AP32", key="SM2", tag="Compañeros · Saʿid ibn Mansur 2587 · ʿUmar y los seis de Bakr ibn Waʾil", specs=["AP-sm2587"],
  title="Saʿid ibn Mansur 2587 (Anas): seis hombres de Bakr ibn Waʾil apostatan en Tustar; ʿUmar: «que los hubiera alcanzado… les habría ofrecido entrar por la puerta por la que salieron; y si no, los habría depositado en la cárcel»",
  ref="Saʿid ibn Mansur, Sunan (ed. al-Aʿzami), «Bab ma yaʾ fi l-futuh», n.º 2587, vol. 2 p. 267; versión paralela en ʿAbd al-Razzaq 18774 (no capturada)", ar_ref="سنن سعيد بن منصور ٢٥٨٧", site=SH, url="https://shamela.ws/book/13122/2640",
  es=["2587 - Nos contó Saʿid, dijo: nos contó Jalid ibn ʿAbd Allah, de Dawud, de ʿAmir [al-Shaʿbi], de Anas ibn Malik, que dijo: «[[k:Apostataron seis hombres de Bakr ibn Waʾil el día de Tustar;]] fui a ver a ʿUmar ibn al-Jattab y me preguntó: ‹¿Qué fue de los hombres?› Me puse a hablar de otra cosa; luego dijo: ‹¿Qué fue de los hombres?› Dije: ‹Fueron matados.› Dijo: [[a:‹Que yo los hubiera alcanzado me habría sido más querido que todo sobre lo que sale el sol.›]] Le dije: [[k:‹¿Y qué otro camino tenían sino la muerte?›]] Dijo: [[a:‹Yo les ofrecía entrar por la puerta por la que habían salido; si lo hacían, bien, y si no, los depositaba en la cárcel.›]]»"],
  prueba="El testimonio más claro de lo que ʿUmar habría hecho en ese caso: ofrecer a los apóstatas volver al islam y, si no lo aceptaban, encarcelarlos. Anas, que estaba en Tustar, le pregunta si no había otro camino que la muerte.",
  ojo="Va en contra de la lectura «el apóstata siempre se mata»: según esta cadena (y ʿAbd al-Razzaq 18774, por al-Shaʿbi desde Anas), la opción de ʿUmar era la cárcel. Contexto: en 18774 estos seis «apostataron y se unieron a los politeístas», es decir, desertaron al enemigo en plena guerra; eso da pie a la lectura «combatiente» (AP16, AP18). Otra cadena distinta de AP31, y por tanto otra tradición del mismo episodio. Sin calificación de la cadena en la página.", uso=USO),

 dict(id="AP33", key="MW1", tag="179 H · Malik, al-Muwatta' 36-25 · «quien cambie su religión»", specs=["AP-mw25"],
  title="Muwatta' de Malik (recensión de Yahya): «Quien cambie su religión, cortadle el cuello» (Zayd ibn Aslam, mursal) y la explicación del propio Malik: zanadiqa sin arrepentimiento; el declarado, con arrepentimiento y, si no, muerte; no alcanza a los dhimmíes",
  ref="Malik ibn Anas, al-Muwatta' (recensión de Yahya ibn Yahya al-Laythi), Kitab al-aqdiya, «Bab al-targhib fi l-qada' bi-l-haqq», n.º 36-25 (numeración de hadithunlocked)", ar_ref="موطأ مالك ٣٦-٢٥", site=HU, url="https://hadithunlocked.com/malik:36-25",
  es=["36-25 - Nos contó Yahya, de Malik, de Zayd ibn Aslam, que el Mensajero de Dios ﷺ dijo: [[k:«Quien cambie su religión, cortadle el cuello.»]] Y el sentido del dicho del Profeta ﷺ —según nuestro parecer, y Dios sabe más— «quien cambie su religión, cortadle el cuello» es que quien sale del islam hacia otra [religión], [[k:como los zanadiqa y semejantes,]] [[a:esos, cuando se les descubre, se les mata y no se les pide arrepentimiento,]] porque no se conoce su arrepentimiento y porque ocultaban la incredulidad y manifestaban el islam; no veo que se les pida arrepentimiento ni que se acepte lo que digan. [[k:Y quien salió del islam hacia otra [religión] y lo manifestó, a ése se le pide el arrepentimiento: si se arrepiente, [bien], y si no, se le mata.]] Y esto: si un grupo estuviera en eso, creo que se les llamaría al islam y se les pediría arrepentimiento; si se arrepienten, se les acepta; y si no se arrepienten, se les mata. [[a:Y con esto no se alude, según nuestro parecer y Dios sabe más, a quien sale del judaísmo al cristianismo]] ni del cristianismo al judaísmo, ni a quien cambia de religión entre todas las religiones salvo el islam; quien sale del islam hacia otra [religión] y lo manifiesta, ése es a quien se alude, y Dios sabe más."],
  prueba="Es el texto base del círculo de Malik (m. 179 H), leído directamente en el Muwatta': Zayd ibn Aslam atribuye al Profeta «quien cambie su religión, cortadle el cuello»; y Malik mismo explica cómo se aplica: a los zanadiqa se les mata sin arrepentimiento; al apóstata declarado se le pide el arrepentimiento y, si no, se le mata; no se aplica a quien pasa de una religión a otra que no sea el islam.",
  ojo="El hadiz es mursal (Zayd ibn Aslam no es Compañero), como advierte Ibn ʿAbd al-Barr (AP13). Las frases «según nuestro parecer…» son de Malik, no del Profeta. La página pone etiquetas de grado («ṣaḥīḥ (Malik)») que son del sitio sobre el conjunto de la obra; no las uso. Coincide con lo que citaba Ibn ʿAbd al-Barr (AP13, AP14): ahora está comprobado en el texto original del Muwatta'. Esta recensión no es la única: otras (Abu Mus'ab, Muhammad ibn al-Hasan) pueden variar; yo solo he leído la de Yahya.", uso=USO),

 dict(id="AP34", key="MW2", tag="179 H · Malik, al-Muwatta' 36-26 · ʿUmar y el apóstata", specs=["AP-mw26"],
  title="Muwatta' de Malik: ʿUmar: «¿y no lo encarcelasteis tres [días], le disteis cada día un pan y le pedisteis que se arrepintiera, por si se arrepentía y volvía al mandato de Dios?»",
  ref="Malik ibn Anas, al-Muwatta' (recensión de Yahya), Kitab al-aqdiya, «Bab al-targhib fi l-qada' bi-l-haqq», n.º 36-26 (numeración de hadithunlocked)", ar_ref="موطأ مالك ٣٦-٢٦", site=HU, url="https://hadithunlocked.com/malik:36-26",
  es=["36-26 - Y me contó Malik, de ʿAbd al-Rahman ibn Muhammad ibn ʿAbd Allah ibn ʿAbd al-Qari, de su padre, que dijo: Vino a ʿUmar ibn al-Jattab un hombre [enviado] de parte de Abu Musa al-Ashʿari, y le preguntó por la gente y le informó. Luego le dijo ʿUmar: «¿Hubo alguna noticia de lejos?» Dijo: «Sí: [[k:un hombre que descreyó después de su islam.]]» Dijo: «¿Y qué hicisteis con él?» Dijo: [[k:«Lo acercamos y le cortamos el cuello.»]] Dijo ʿUmar: [[k:«¿Y no lo encarcelasteis tres [días], le dabais cada día un pan y le pedisteis que se arrepintiera, por si se arrepentía y volvía al mandato de Dios?»]] Luego dijo ʿUmar: [[a:«¡Oh Dios! No estuve presente, no [lo] ordené y no [lo] aprobé cuando me llegó.»]]"],
  prueba="El mismo episodio de ʿUmar y el apóstata de Tustar en el propio Muwatta' de Malik: de aquí deduce la escuela maliki el plazo de tres días y la petición de arrepentimiento (Ibn Qudama lo cita así en AP40; Ibn Rushd, en AP43).",
  ojo="La versión del Muwatta' no dice que ʿUmar mandara matar tras el plazo: solo que debieron encarcelarlo, alimentarlo y pedirle arrepentimiento «por si volvía». La página lo etiqueta «mawquf · mursal» y «ṣaḥīḥ (Malik)»: etiquetas del sitio. (Una búsqueda web da que al-Bayhaqi y al-Shafiʿi lo consideran «cortado» y al-Albani de buena cadena; no lo leí en esas obras.) Lo cuenta el hijo de ʿAbd al-Rahman, de su padre: no sé si éste estuvo presente; el texto no lo dice.", uso=USO),

 dict(id="AP35", key="MUD1", tag="240 H · Sahnun, al-Mudawwana · la apóstata", specs=["AP-mud558"],
  title="al-Mudawwana (Sahnun, por Ibn al-Qasim): sobre la apóstata: «no se la demora: se le pide que se arrepienta y, si no se arrepiente, se le corta el cuello»",
  ref="Sahnun, al-Mudawwana al-kubra (doctrina de Malik por Ibn al-Qasim), «Sukna l-murtadda», vol. 2 p. 55", ar_ref="المدونة ج٢ ص٥٥", site=SH, url="https://shamela.ws/book/587/558",
  es=["[Pregunté:] ¿Tiene la apóstata derecho a manutención y alojamiento, si está embarazada, mientras dure el embarazo? Dijo: Sí, porque el hijo se atribuye al padre; por eso le corresponde la manutención. [[a:Y si no está embarazada de modo conocido, no se la demora:]] [[k:se le pide que se arrepienta y, si no se arrepiente, se le corta el cuello;]] así que no veo que tenga derecho a manutención durante esa petición de arrepentimiento, porque ya se separó de él; y si regresa al islam, [[a:será un repudio definitivo]] y tendrá derecho al alojamiento."],
  prueba="En la Mudawwana, la obra de Sahnun (m. 240 H) que recoge la doctrina de Malik por Ibn al-Qasim, se da por sentado que a la apóstata mujer se le pide el arrepentimiento y, si no se arrepiente, se le corta el cuello: la escuela maliki mata a la mujer apóstata (contra los hanafíes, AP23, AP45).",
  ojo="Es una frase incidental, en un capítulo sobre alojamiento y manutención de la divorciada (sukna), en boca de quien responde (Ibn al-Qasim): no dice aquí «qala Malik», así que no lo atribuyo a Malik con certeza. No hay en la Mudawwana (Shamela, 2437 páginas recorridas por mí con búsqueda de «مرتد/استتاب/ارتد/زنديق») un capítulo propio sobre la ejecución del apóstata con hadices; las menciones están repartidas (matrimonio, tadbir, herencia, qadhf, jawarij): ver AP36.", uso=USO),

 dict(id="AP36", key="MUD2", tag="240 H · Sahnun, al-Mudawwana · la muerte cubre los castigos", specs=["AP-mud730", "AP-mud731"],
  title="al-Mudawwana: el apóstata que persiste: «la muerte cubre todos los castigos, salvo la calumnia, que se paga antes con azotes», cubre también el talión, y sus bienes pasan a la comunidad de los musulmanes",
  ref="Sahnun, al-Mudawwana al-kubra, «Hudud al-murtadd wa-l-murtadda wa-faraʾiduhuma», vol. 2 pp. 227-228", ar_ref="المدونة ج٢ ص٢٢٧-٢٢٨", site=SH, url="https://shamela.ws/book/587/730 · https://shamela.ws/book/587/731",
  es=["[Pregunté:] Y [[k:si persiste en su apostasía, ¿la muerte cubre todos los castigos que pesan sobre él,]] salvo la calumnia (firya),",
      "[[k:pues se le azota y luego se le mata?]] Dijo: Sí. Pregunté: [[k:¿Y la muerte cubre también el talión que se debe a las personas?]] Dijo: Sí. Pregunté: [[a:¿Conservas esto de Malik?]] Dijo: [[a:Sí.]]",
      "Pregunté: ¿Y el apóstata que hace testamentos y es muerto en su incredulidad: son exigibles los legados? Dijo: Malik me dijo: [[k:«No lo heredan sus herederos»;]] así que opino que no hay nada para los legatarios, pues no es válido el testamento sino sobre lo propio, y [[a:este bien no es del apóstata: ha pasado a ser de la comunidad de los musulmanes.]]"],
  prueba="La doctrina maliki tal como la recoge Sahnun: el apóstata que persiste es muerto; esa muerte «cubre» los demás castigos que pesaran sobre él (se le azota antes por calumnia) y el talión; y sus bienes pasan a la comunidad de los musulmanes, no a sus herederos. Todo ello presupone que se le ejecuta.",
  ojo="El texto presupone la ejecución («si persiste en su apostasía»): no la justifica con hadices ni da el plazo; es un tratamiento de consecuencias. El heredero que no hereda (Mudawwana) contrasta con ʿAbd al-Razzaq 18787 (AP25), donde la herencia va a los hijos musulmanes, y con la regla de otras escuelas. La frase «¿Conservas esto de Malik? Sí» es de Ibn al-Qasim a Sahnun, no del propio Malik. La primera frase cruza el pliegue de página 227→228, por eso hay dos capturas.", uso=USO),

 dict(id="AP37", key="IM1", tag="319 H · Ibn al-Mundhir, Kitab al-Ijmaʿ 719 · consenso", specs=["AP-im128"],
  title="Ibn al-Mundhir, Kitab al-Ijmaʿ, n.º 719: «Los sabios convinieron en que si [el siervo] apostata, se le pide arrepentimiento y no se arrepiente, es muerto; y no conozco en ello desacuerdo»",
  ref="Ibn al-Mundhir (m. 319 H), Kitab al-Ijmaʿ (ed. Abu ʿAbd al-Aʿla; Shamela), «Kitab al-murtadd», n.º 719, p. 132", ar_ref="كتاب الإجماع لابن المنذر ٧١٩", site=SH, url="https://shamela.ws/book/151100/128",
  es=["719 - Y los sabios convinieron en que el siervo [= ‹al-ʿabd›] que apostata, y se le pide el arrepentimiento, [[k:y no se arrepiente: es muerto;]] [[a:y no conozco en ello desacuerdo.]]"],
  prueba="Ibn al-Mundhir, el especialista en registrar consensos (ijmaʿ) y desacuerdos, registra como consenso que el apóstata al que se pide arrepentimiento y no se arrepiente es muerto.",
  ojo="(1) La edición dice «al-ʿabd» (literalmente «el siervo, el esclavo»); no sé si es «el siervo de Dios» (el creyente) o una variante; no comparé otra edición. (2) Su consenso ya incluye pedir el arrepentimiento; otros (ʿUbayd ibn ʿUmayr, Tawus, al-Hasan; Ibn Taymiyya, AP17) no lo exigen. (3) «No conozco desacuerdo» es una fórmula de conocimiento personal: no afirma que nadie discrepe. (4) Ibn Qudama (9/6, siguiente página) dice que el dicho «en el acto» —si se arrepiente en el acto, bien; si no, es muerto— es el de Ibn al-Mundhir, es decir, que él mismo era partidario de no dar plazo largo.", uso=USO),

 dict(id="AP38", key="IM2", tag="319 H · Ibn al-Mundhir, Kitab al-Ijmaʿ 725 · testigos", specs=["AP-im129"],
  title="Ibn al-Mundhir, Kitab al-Ijmaʿ, n.º 725: «Los sabios convinieron en que el testimonio de dos testigos debe aceptarse sobre la apostasía y que se mata por él si no vuelve al islam; se singularizó al-Hasan: cuatro»",
  ref="Ibn al-Mundhir, Kitab al-Ijmaʿ, «Kitab al-murtadd», n.º 725, p. 133", ar_ref="كتاب الإجماع لابن المنذر ٧٢٥", site=SH, url="https://shamela.ws/book/151100/129",
  es=["725 - Y los sabios convinieron en que el testimonio de dos testigos debe aceptarse sobre la apostasía, [[k:y que el hombre es muerto por su testimonio si no vuelve al islam.]] [[a:Y se singularizó al-Hasan, que dijo: «No se acepta, en [caso de] muerte, sino el testimonio de cuatro.»]]"],
  prueba="Otro consenso que registra Ibn al-Mundhir: la apostasía se prueba con dos testigos y, probada, se mata a quien no vuelve al islam; solo al-Hasan [al-Basri] discrepa, pidiendo cuatro.",
  ojo="Es un consenso «de los sabios» que él mismo acompaña de una excepción con nombre (al-Hasan): para Ibn al-Mundhir, «ijmaʿ» admite excepciones que él registra. La línea de arriba de la página (final del n.º 724) añade «no conocemos a nadie que haya impuesto al apóstata una sola vez un castigo (adab) cuando vuelve al islam» (queda visible en la captura, sin resaltar). Texto de Shamela.", uso=USO),

 dict(id="AP39", key="IQ1", tag="620 H · Ibn Qudama, al-Mughni 9/3-4 · ijmaʿ", specs=["AP-iq3", "AP-iq4a"],
  title="Ibn Qudama, al-Mughni: «Los sabios convinieron en la obligatoriedad de matar al apóstata… y no se rechazó eso; fue, pues, consenso»; en la misma página: mujeres: ʿAli, al-Hasan y Qatada: se las esclaviza y no se las mata",
  ref="Ibn Qudama (m. 620 H), al-Mughni (ed. Maktabat al-Qahira), «Kitab al-murtadd», vol. 9 pp. 3-4", ar_ref="المغني لابن قدامة ج٩ ص٣-٤", site=SH, url="https://shamela.ws/book/8463/3917 · https://shamela.ws/book/8463/3918",
  es=["El apóstata es el que vuelve de la religión del islam a la incredulidad. Dijo Dios Altísimo: {Y quien de vosotros apostate de su religión y muera siendo incrédulo, esos han perdido sus obras en el mundo y en la otra vida, y esos son la gente del Fuego, en él permanecerán} [2:217]. Y dijo el Profeta: «Quien cambie su religión, matadlo.» [[k:Y los sabios convinieron en la obligatoriedad de matar al apóstata.]] [[a:Y se transmitió esto de Abu Bakr, ʿUmar, ʿUthman, ʿAli, Muʿadh, Abu Musa, Ibn Abbas, Jalid y otros,]] [[k:y no se rechazó eso; fue, pues, consenso.]] (7083) Cuestión: [dijo]: «Y quien apostate del islam, hombres y mujeres…»",
      "[[k:Primero: que no hay diferencia entre hombres y mujeres en la obligatoriedad de matar.]] Se transmitió de Abu Bakr y ʿAli —Dios esté complacido con ellos—, y lo dijo al-Hasan, al-Zuhri, al-Nakhaʿi, Makhul, Hammad, Malik, al-Layth, al-Awzaʿi, al-Shafiʿi e Ishaq. [[a:Y se transmitió de ʿAli, al-Hasan y Qatada que [la apóstata] es esclavizada y no muerta;]] pues Abu Bakr esclavizó a las mujeres de los Banu Hanifa y a su descendencia, y dio a ʿAli una de ellas, y le dio a luz a Muhammad ibn al-Hanafiyya; y eso fue ante los Compañeros y no se rechazó, de modo que fue consenso. Y dijo Abu Hanifa: [[a:se la obliga al islam con prisión y golpes, y no se la mata,]] por el dicho del Profeta: «No matéis a una mujer»…",
      "Y transmitió al-Daraqutni que una mujer llamada Umm Marwan apostató del islam y su asunto llegó al Profeta; [[k:mandó que se le pidiera arrepentimiento y, si no se arrepentía, que fuera muerta.]] Y porque es [[k:una persona responsable que cambió la religión de la verdad por la falsedad, de modo que se la mata como al hombre.]] Y en cuanto a la prohibición del Profeta de matar a la mujer, [[a:se refiere a la incrédula de origen]]…"],
  prueba="Ibn Qudama (m. 620 H), el gran jurista hanbali, enuncia el consenso en una frase —«los sabios convinieron en la obligatoriedad de matar al apóstata»— y lo respalda con el hadiz y con la lista de Compañeros a quienes se transmite («y no se rechazó»). La frase que no pude leer en el escaneo está leída ahora en la página legible de Shamela (vol. 9 p. 3).",
  ojo="Es un consenso por silencio («no se rechazó»), no una encuesta: es la fórmula de Ibn Qudama. En la misma página él registra que Abu Hanifa y ciertas transmisiones de ʿAli, al-Hasan y Qatada discrepan sobre las mujeres; su «consenso» se refiere a la regla general (el apóstata se mata) y deja a un lado esa excepción, que él mismo trae. En la página siguiente (AP41) rechaza la opinión de al-Nakhaʿi como contraria al consenso. El relato de Umm Marwan lo atribuye a al-Daraqutni sin cadena: yo no lo he buscado en al-Daraqutni.", uso=USO),

 dict(id="AP40", key="IQ2", tag="620 H · Ibn Qudama, al-Mughni 9/4-5 · el arrepentimiento", specs=["AP-iq4b", "AP-iq5"],
  title="Ibn Qudama, al-Mughni: «no se mata hasta que se le pide arrepentimiento tres [días]»: la mayoría; ʿUbayd ibn ʿUmayr, Tawus y al-Hasan: no hace falta; el relato de ʿUmar (Muwatta'): «¿no lo encarcelasteis?»",
  ref="Ibn Qudama, al-Mughni, «Kitab al-murtadd», vol. 9 pp. 4-5", ar_ref="المغني لابن قدامة ج٩ ص٤-٥", site=SH, url="https://shamela.ws/book/8463/3918 · https://shamela.ws/book/8463/3919",
  es=["(7086) Tercero: que no se le mata hasta que se le pide el arrepentimiento tres [días]. [[k:Éste es el dicho de la mayoría de los sabios;]] entre ellos ʿUmar, ʿAli, ʿAta', al-Nakhaʿi, Malik, al-Thawri, al-Awzaʿi, Ishaq y la gente del raʾy [los hanafíes]. Y es uno de los dos dichos de al-Shafiʿi. [[a:Y se transmite de Ahmad otra versión: que no es obligatorio pedirle arrepentimiento, pero es preferible.]] Y éste es el segundo dicho de al-Shafiʿi,",
      "[[k:y es dicho de ʿUbayd ibn ʿUmayr y de Tawus. Y se transmite eso de al-Hasan,]] por el dicho del Profeta: «Quien cambie su religión, matadlo», [[a:y no mencionó que se le pidiera arrepentimiento.]]",
      "Y transmitió Malik en el Muwatta', de ʿAbd al-Rahman ibn Muhammad ibn ʿAbd Allah ibn ʿAbd al-Qari, de su padre, que un hombre vino a ʿUmar de parte de Abu Musa, y le dijo ʿUmar: «¿Hubo alguna noticia de lejos?» Dijo: «Sí: un hombre descreyó después de su islam.» Dijo: «¿Qué hicisteis con él?» Dijo: «Lo acercamos y le cortamos el cuello.» Dijo ʿUmar: «[[k:¿Por qué no lo encarcelasteis tres [días] y le disteis cada día un pan y le pedisteis que se arrepintiera,]] [[a:por si se arrepentía o volvía al mandato de Dios?]] ¡Oh Dios! No estuve presente, no [lo] ordené y no [lo] aprobé cuando me llegó.»",
      "[…] Una vez establecida la obligación de pedir arrepentimiento, [[k:su plazo es de tres días; se transmitió de ʿUmar.]] Y lo dijo Malik, Ishaq y la gente del raʾy; y es uno de los dos dichos de al-Shafiʿi. Y dijo en el otro: [[a:si se arrepiente en el acto, [bien], y si no, es muerto]] [continúa en la página siguiente]…"],
  prueba="Ibn Qudama resume las posturas: la mayoría exige pedir arrepentimiento y da tres días (Malik, hanafíes, uno de los dos dichos de al-Shafiʿi); otros (ʿUbayd ibn ʿUmayr, Tawus, al-Hasan; una versión de Ahmad; el otro dicho de al-Shafiʿi) no lo exigen, pues el hadiz «quien cambie su religión» no lo menciona; y apoya el plazo en el relato de ʿUmar del Muwatta' (AP34).",
  ojo="Ibn Qudama cita aquí a al-Nakhaʿi entre quienes piden arrepentimiento tres días y, en la página siguiente (AP41), cita su «se le pide siempre»: no resuelve la tensión. La lista de nombres es de Ibn Qudama; no verifiqué cada atribución. Y no dice «se mata sin más»: lo que fundamenta es el plazo, y «tres días» sale del relato de ʿUmar (cuya versión en el Muwatta', AP34, no manda matar tras el plazo). En la página siguiente dice que el dicho «en el acto» es el más sólido de los dos de al-Shafiʿi y el de Ibn al-Mundhir (AP37).", uso=USO),

 dict(id="AP41", key="IQ3", tag="620 H · Ibn Qudama, al-Mughni 9/6 · al-Nakhaʿi y la duda", specs=["AP-iq6"],
  title="Ibn Qudama, al-Mughni 9/6: al-Nakhaʿi: «se le pide arrepentimiento siempre» (para Ibn Qudama, «contrario a la sunna y al consenso»); la apostasía nace de una duda; «si no se arrepiente, es muerto, con la espada, no con fuego»",
  ref="Ibn Qudama, al-Mughni, «Kitab al-murtadd», vol. 9 p. 6", ar_ref="المغني لابن قدامة ج٩ ص٦", site=SH, url="https://shamela.ws/book/8463/3920",
  es=["[[k:Y dijo al-Zuhri: «Se le llama tres veces; si se niega, se le corta el cuello.»]] Esto se parece al dicho de al-Shafiʿi. [[a:Y dijo al-Nakhaʿi: «Se le pide arrepentimiento siempre [abadan].» Y esto lleva a que nunca sea muerto, y es contrario a la sunna y al consenso.]] Y de ʿAli se transmite que pidió arrepentimiento a un hombre durante un mes.",
      "Y [para nosotros está] el relato de ʿUmar, y porque [[k:la apostasía solo ocurre por una duda (shubha) que no desaparece en el acto,]] [[a:por lo que hay que esperar un plazo en el que reflexione;]] y lo más oportuno son tres días, por la tradición y porque es un plazo breve. Y conviene presionarlo y encarcelarlo durante el plazo, por el dicho de ʿUmar: «¿Por qué no lo encarcelasteis y le disteis cada día un pan?»; y repetirle la exhortación, por si se le ablanda el corazón y vuelve a su religión.",
      "Cuarto: [[k:que si no se arrepiente es muerto,]] por lo que hemos dicho antes; [[k:y es el dicho de la generalidad de los juristas, y se le mata con la espada;]] [[a:y no se le quema con fuego.]]"],
  prueba="Ibn Qudama explica por qué se concede el plazo (la apostasía nace de una duda que no se disipa al instante: hay que dar tiempo, encarcelar y exhortar) y concluye que, si no se arrepiente, se le mata —con espada, no con fuego— «y es el dicho de la generalidad de los juristas».",
  ojo="El texto trae a la vez la disidencia de al-Nakhaʿi (que él rechaza como contraria al consenso: AP28 confirma el «abadan») y la explicación «por duda», que presenta la ejecución como último recurso tras plazo, cárcel y exhortación. Las atribuciones (al-Zuhri, ʿAli, al-Nakhaʿi) son de Ibn Qudama; la de al-Nakhaʿi la comprobé en ʿAbd al-Razzaq 18775 (AP28). La frase «contrario a la sunna y al consenso» es de Ibn Qudama, no de al-Nakhaʿi.", uso=USO),

 dict(id="AP42", key="BR1", tag="520 H · Ibn Rushd (el abuelo), al-Bayan 16/378-379 · la persistencia", specs=["AP-br378", "AP-br379a"],
  title="Ibn Rushd (el abuelo), al-Bayan wa-l-tahsil: Malik: «no veo castigo si vuelve al islam; la muerte era si persistía»; Ibn Rushd: se le perdona por Corán 8:38, y «la muerte se le debe por persistir en la incredulidad»",
  ref="Ibn Rushd al-Yadd (m. 520 H), al-Bayan wa-l-tahsil, «Kitab al-murtaddin wa-l-muharibin», vol. 16 pp. 378-379", ar_ref="البيان والتحصيل ج١٦ ص٣٧٨-٣٧٩", site=SH, url="https://shamela.ws/book/21751/7806 · https://shamela.ws/book/21751/7807",
  es=["[Del libro de los juicios, segundo:] Y se preguntó a Malik sobre el musulmán que apostata del islam y al que se le ofrece el islam y se hace musulmán: ¿opina que se le aplica algún castigo (hadd) por lo que hizo con su apostasía del islam a la incredulidad? Dijo: [[k:«No veo que se le aplique castigo si vuelve al islam;]] [[k:la muerte era lo que le correspondía si hubiera persistido en el cristianismo;]] [[a:pero si vuelve al islam, no se le aplica nada.»]]",
      "Dijo Muhammad ibn Rushd: En cuanto al apóstata, [[a:no se le aplicó castigo por lo que hizo con su apostasía si volvió al islam,]] por el dicho de Dios Altísimo: [[k:{Di a quienes descreen: si desisten, se les perdonará lo pasado}]]",
      "[Y sobre la comparación de Sahnun con el testigo que se retracta:] [… no es correcta,] [[a:porque el apóstata solo quedó libre de castigo por la aleya mencionada, y no porque, si se le castigara, nadie se atrevería a volver al islam por miedo al castigo;]] [[k:pues la muerte se le debe por persistir en la incredulidad,]] [[a:y eso es más duro que el castigo que temería si volviera al islam;]] así que los dos casos no son semejantes."],
  prueba="Ibn Rushd el abuelo (m. 520 H), el gran maliki cordobés, deja una formulación clave de la doctrina: la muerte «se debe por persistir en la incredulidad» y quien vuelve al islam queda libre de castigo (con Corán 8:38 como base). Es la lectura que pone el centro en negarse a volver, no en el acto de apostatar.",
  ojo="Cuidado con usarlo en una sola dirección: apoya que la pena es la muerte si persiste, y a la vez que el apóstata que vuelve no tiene castigo. El pasaje comenta una consulta a Malik recogida en la ʿUtbiyya (Kitab al-aqdiya), no es un tratado sobre la apostasía. La cita de Sahnun sobre el testigo que se retracta explica el contexto del razonamiento: Ibn Rushd rechaza la comparación; por eso las dos últimas líneas van entre corchetes de contexto.", uso=USO),

 dict(id="AP43", key="BR2", tag="520 H · Ibn Rushd (el abuelo), al-Bayan 16/379-380 · plazo y Compañeros", specs=["AP-br379b", "AP-br380"],
  title="Ibn Rushd (el abuelo), al-Bayan: Malik: «tres días… me parece bien; no es lo que hace la gente»; hay sabios que matan sin pedir arrepentimiento; y «no se conservó de los Compañeros desacuerdo en pedir arrepentimiento; discreparon solo en su plazo»",
  ref="Ibn Rushd al-Yadd, al-Bayan wa-l-tahsil, vol. 16 pp. 379-380", ar_ref="البيان والتحصيل ج١٦ ص٣٧٩-٣٨٠", site=SH, url="https://shamela.ws/book/21751/7807 · https://shamela.ws/book/21751/7808",
  trnote="Traducción literal propia; entre corchetes, aclaraciones. La cláusula «ولا يأتي من الاستظهار الأخير» es de sentido dudoso; la dejo aproximada. ",
  es=["[Y se preguntó a Malik] sobre el que vuelve al islam [tras apostatar]: ¿tiene un plazo en el que se le deje? Dijo: [[k:«Se dice: tres días, y lo veo bien»,]] y me agrada, y no llega [a la cláusula del] último istizhar [plazo extra; sentido dudoso]. Y se le preguntó por el dicho de ʿUmar: «¿No lo encarcelasteis tres [días], y le disteis cada día un pan?»: ¿se ha de esperar así al que descree tras su islam, o se le pide arrepentimiento en el acto? Dijo: «No veo en esto inconveniente, [[a:pero no es lo que sigue la generalidad de la gente.»]]",
      "Dijo Muhammad ibn Rushd: Su dicho «y no es lo que sigue la generalidad de la gente» quiere decir [lo del plazo de] tres [días]; y es posible que quiera decir que la generalidad no sigue la petición de arrepentimiento al apóstata, [[k:pues hay sabios que opinan que se le mata sin pedirle arrepentimiento, según el sentido aparente del dicho del Profeta: ‹Quien cambie su religión, matadlo›]], [[a:y es el dicho de ʿAbd al-ʿAziz ibn Abi Salama…]] y argumentó con lo que se transmite de que Abu Musa al-Ashʿari se detuvo ante Muʿadh ibn Jabal, con un musulmán que se había hecho judío delante, y [Muʿadh] le dijo: «Baja, Abu Musa»; dijo: «No, por Dios, no bajaré hasta que éste sea muerto.» [Y dijo:] si [Muʿadh] hubiera visto necesaria la petición de arrepentimiento, no lo habría dicho.",
      "Y algunos transmisores de Abu Musa dijeron, sobre este hadiz, que ya le había pedido arrepentimiento durante días antes; y eso es lo cierto, si Dios quiere, [[k:porque no se ha conservado de los Compañeros —Dios esté complacido con ellos— desacuerdo en cuanto a pedir arrepentimiento al apóstata,]] [[a:sino que discreparon en su plazo: unos dijeron que se le pide una sola vez, otros un mes, otros tres días;]] y éste es el que sigue la mayoría de los sabios."],
  prueba="Ibn Rushd da la doctrina mayoritaria (tres días, de Malik), registra que algunos sabios matan sin pedir arrepentimiento (ʿAbd al-ʿAziz ibn Abi Salama, con el caso de Muʿadh y Abu Musa), y afirma una tesis historiográfica: que de los Compañeros no se conserva desacuerdo en pedir arrepentimiento, solo en el plazo (una vez, un mes, tres días).",
  ojo="La frase «no se conservó de los Compañeros desacuerdo» es afirmación de Ibn Rushd, no demostración: él mismo registra a quien no pide arrepentimiento, e Ibn Qudama (AP40) cita a ʿUbayd ibn ʿUmayr, Tawus y al-Hasan (tabiʿun). En esta cita de Muʿadh y Abu Musa los papeles aparecen invertidos respecto a Bujari 6923 (AP07): allí es Muʿadh quien no se sienta hasta que lo maten; aquí es Abu Musa quien no baja. No he resuelto si es variante o error. Se refiere al caso de Bujari 6923 / Abu Dawud 4356 (AP07, AP08).", uso=USO),

 dict(id="AP44", key="BR3", tag="520 H · Ibn Rushd (el abuelo), al-Bayan 16/391 · el zindiq", specs=["AP-br391"],
  title="Ibn Rushd (el abuelo), al-Bayan 16/391: el que oculta su religión (zandaqa, judaísmo, cristianismo) se mata sin arrepentimiento; el apóstata declarado, con arrepentimiento; «acuerdo en la escuela»; contra: al-Shafiʿi y ʿAbd al-ʿAziz ibn Abi Salama",
  ref="Ibn Rushd al-Yadd, al-Bayan wa-l-tahsil, vol. 16 p. 391", ar_ref="البيان والتحصيل ج١٦ ص٣٩١", site=SH, url="https://shamela.ws/book/21751/7819",
  es=["Cuestión. Dijo Ibn al-Qasim: «Si [el hombre] oculta una religión y viene arrepentido de ella, se le acepta el arrepentimiento y no es muerto. Y si se le sorprende en una religión que oculta, como la zandaqa, el judaísmo o el cristianismo, y era una religión que ocultaba, [[k:es muerto y no se le pide arrepentimiento,]] [[a:porque no se conoce su arrepentimiento;]] y si niega lo que se testificó contra él, no se acepta su negación y es muerto, sin que se le pida arrepentimiento; y si alega arrepentimiento, tampoco se acepta su arrepentimiento.»",
      "Dijo Muhammad ibn Rushd: Esto es cosa acordada en la escuela [maliki]: [[k:que al apóstata que manifiesta la incredulidad se le pide arrepentimiento, y que el zindiq y quien oculta el judaísmo, el cristianismo o cualquier religión distinta del islam es muerto sin que se le pida arrepentimiento;]] [[a:y al-Shafiʿi opina que a ambos se les pide arrepentimiento, y ʿAbd al-ʿAziz ibn Abi Salama opina que ambos son muertos y a ninguno se le pide arrepentimiento,]] según el sentido aparente del dicho del Profeta…"],
  prueba="La doctrina maliki sobre dos casos: el apóstata declarado (arrepentimiento y, si no, muerte) y quien oculta su religión (muerte sin arrepentimiento); y las dos posiciones contrarias (al-Shafiʿi y ʿAbd al-ʿAziz ibn Abi Salama). Coincide con lo que dice Malik en el Muwatta' (AP33).",
  ojo="El «acuerdo» es «en la escuela» (fi l-madhhab), no entre todos los sabios; y justo después registra dos opiniones contrarias. La frase final se corta al final de la página: cita el hadiz «man baddala dinahu…», que continúa en la página siguiente. Aquí «religión que oculta» incluye el judaísmo y el cristianismo ocultos de un musulmán que fingía serlo.", uso=USO),

 dict(id="AP45", key="BR4", tag="520 H · Ibn Rushd (el abuelo), al-Bayan 16/392 · las mujeres", specs=["AP-br392"],
  title="Ibn Rushd (el abuelo), al-Bayan 16/392: Abu Bakr pide arrepentimiento a Umm Qirfa y, al no arrepentirse, le corta el cuello; contra los iraquíes: «lo correcto es que se la mata si no se hace musulmana»",
  ref="Ibn Rushd al-Yadd, al-Bayan wa-l-tahsil, vol. 16 p. 392", ar_ref="البيان والتحصيل ج١٦ ص٣٩٢", site=SH, url="https://shamela.ws/book/21751/7820",
  es=["[…] Y me contó Ibn al-Qasim, de al-Layth ibn Saʿd, de Saʿid ibn ʿAbd al-ʿAziz al-Tanukhi: que Abu Bakr al-Siddiq [[k:pidió arrepentimiento a una mujer de los Banu Fazara, de Qays, llamada Umm Qirfa, que había apostatado del islam; no se arrepintió y le cortó el cuello.]]",
      "Dijo Muhammad ibn Rushd: Este hadiz solo vino como prueba contra la gente de Iraq [los hanafíes], que dicen de la mujer que si apostata se la encarcela y se la obliga al islam, y no se la mata. [[a:Y se transmitió eso de Ibn Abbas y de al-Hasan,]] y dijeron: si se hace musulmana no se la esclaviza, como el hombre que apostata y luego se arrepiente. Y dijo al-Hasan: si se hace musulmana será esclava de los musulmanes, como la libre capturada. [[k:Y lo correcto es que se la mata si no se hace musulmana,]] porque el dicho del Profeta «quien cambie su religión, matadlo» es general y abarca a hombres y mujeres, y se transmitió de él pedir arrepentimiento a una mujer que apostató…",
      "Y los iraquíes se apoyaron, para su postura de que no se mata a la apóstata, en la prohibición del Profeta de [matar] mujeres de los incrédulos en guerra, y eso no es argumento: pues no se las mata porque no combaten, según su dicho en el hadiz cuando se detuvo ante la mujer muerta: «Ésta no combatía». [[k:Así que la mujer, si no combate, no es muerta, y si combate, es muerta;]] y lo mismo el hombre que se sabe que no combate, como los monjes y semejantes, no es muerto; así que no hay diferencia en esto entre hombres y mujeres"],
  prueba="Sobre las mujeres: un maliki (m. 520 H) cita el caso de Abu Bakr y Umm Qirfa (arrepentimiento y, si no, muerte) y responde al argumento hanafí de la prohibición de matar mujeres: era para las que no combaten. También recoge que los de Iraq (hanafíes) sostienen lo contrario, y que eso se transmitió de Ibn Abbas y de al-Hasan.",
  ojo="La cadena que da (Ibn al-Qasim ← al-Layth ← Saʿid ibn ʿAbd al-ʿAziz ← Abu Bakr) no nombra intermediarios: Saʿid es muy posterior a Abu Bakr. Es una cita de ʿUtbiyya, no un hadiz calificado. Hay otra mujer, Umm Qirfa de Fazara, en la sira (ejecutada en una expedición de Zayd ibn Haritha); no he comprobado si hay relación. Y que Ibn Abbas «no mataba a la mujer» es lo que dice Ibn Rushd aquí; AP23 da la cadena que usan los hanafíes (débil, por el editor).", uso=USO),

 dict(id="AP46", key="BM1", tag="595 H · Ibn Rushd (el nieto), Bidayat al-mujtahid 4/242 · acuerdo", specs=["AP-bm242"],
  title="Ibn Rushd (el nieto), Bidayat al-mujtahid: «El apóstata, si se le captura antes de que combata, acordaron que se mata al hombre»; discrepan sobre la mujer y sobre pedir arrepentimiento",
  ref="Ibn Rushd al-Hafid (m. 595 H), Bidayat al-mujtahid wa-nihayat al-muqtasid, «Kitab al-hiraba», «Bab fi hukm al-murtadd», vol. 4 p. 242", ar_ref="بداية المجتهد ونهاية المقتصد ج٤ ص٢٤٢", site=SH, url="https://shamela.ws/book/21739/929",
  es=["Capítulo sobre el juicio del apóstata. Y el apóstata, si se le captura antes de que combata, [[k:acordaron que se mata al hombre,]] por su dicho —la paz sea con él—: «Quien cambie su religión, matadlo». [[a:Discreparon sobre la muerte de la mujer, y si se le pide arrepentimiento antes de matarla.]] La mayoría dijo: se mata a la mujer; y Abu Hanifa dijo: no se la mata, y la asemejó a la incrédula de origen. Y la mayoría se apoyó en la generalidad del dicho; [[a:y un grupo aislado dijo: se la mata aunque vuelva al islam.]] En cuanto al pedir arrepentimiento, [[k:Malik lo condicionó en su muerte, según lo que transmitió de ʿUmar,]] [[a:y otros dijeron: no se acepta su arrepentimiento.]]"],
  prueba="Ibn Rushd el nieto (m. 595 H), en el manual de comparación de escuelas más usado entre los malikies, escribe que «acordaron que se mata al hombre» apóstata no combatiente, apoyándose en el hadiz de Ibn Abbas, y recoge las discrepancias sobre la mujer y sobre pedir arrepentimiento.",
  ojo="El «acordaron» se refiere al hombre; la propia frase siguiente abre los desacuerdos (mujer, arrepentimiento). Y «otros dijeron: no se acepta su arrepentimiento» significa que hay quien mata aunque se arrepienta. No es un tratado sobre la apostasía: es una sección breve al final del libro de la hiraba. La frase «Malik lo condicionó… según lo que transmitió de ʿUmar» remite a Muwatta' 36-26 (AP34).", uso=USO),

 dict(id="AP47", key="RM1", tag="520 H · Ibn Rushd (el abuelo), al-Muqaddimat 1/141 · «por consenso»", specs=["AP-rm141"],
  title="Ibn Rushd (el abuelo), al-Muqaddimat: quien niega que la oración sea obligatoria es incrédulo: «se le pide arrepentimiento y, si no, se le mata, y su bien es de los musulmanes, como el apóstata cuando es muerto por su apostasía, por consenso de los sabios, sin desacuerdo»",
  ref="Ibn Rushd al-Yadd, al-Muqaddimat al-mumahhidat, «Kitab al-salat», vol. 1 p. 141", ar_ref="المقدمات الممهدات ج١ ص١٤١", site=SH, url="https://shamela.ws/book/21735/134",
  es=["[…] Y quien niega la obligatoriedad de la oración es incrédulo; [[k:se le pide arrepentimiento y, si no se arrepiente, es muerto,]] y su bien pertenece a los musulmanes, [[a:como el apóstata cuando es muerto por su apostasía, por consenso de los sabios, sin desacuerdo entre ellos en ello.]]"],
  prueba="En otro libro suyo, Ibn Rushd el abuelo da por hecho que el apóstata es muerto por su apostasía y lo califica de «consenso de los sabios, sin desacuerdo» (en una frase incidental, al tratar de quien niega la oración).",
  ojo="La frase es ambigua: el «consenso» puede referirse a que el apóstata sea muerto, o a que su bien pase a los musulmanes (la comparación va ligada a ese punto), o a ambas cosas. Se dice de paso: su tratamiento propio está en el Bayan (AP42–AP45). En la «Kitab al-muharibin wa-l-murtaddin» de las Muqaddimat (vol. 3 pp. 227-238) encontré, por búsqueda en esas páginas, solo el caso del salteador que apostata (p. 237) y no un tratamiento general de la apostasía.", uso=USO),
]
